{
  "findings": [
    {
      "ref": "[D176]",
      "area": "contact",
      "claim": "A parent reports that strangers can message or voice chat with your child, and it is on by default.",
      "stance": "risk",
      "quote": "When setting up an account it checks to verify age requirements, but it's pretty easy for a savvy kid to fake their birthdate to gain access. Profiles connect through Facebook or email, and users interact with anyone else playing the game at the same time. They can add friends and then send private messages or openly chat with anyone in the same room or location in the game."
    },
    {
      "ref": "[D176]",
      "area": "money",
      "claim": "A parent reports that the app pushes in-app purchases to access full features.",
      "stance": "risk",
      "quote": "Playable without in-app purchases, but access to full array of clothes, furniture, and destinations requires it."
    },
    {
      "ref": "[D176]",
      "area": "data",
      "claim": "A parent reports that the app collects personal data including birth date and location, and can share it with third parties.",
      "stance": "risk",
      "quote": "The privacy policy reiterates that users must be at least 13 and specifies that any personal information shared in the game, including birth date and location, even through chat and private message, can be captured, stored, and used."
    },
    {
      "ref": "[D176]",
      "area": "age_gating",
      "claim": "A parent reports that the age gate can be easily bypassed by faking a birthdate.",
      "stance": "risk",
      "quote": "When setting up an account it checks to verify age requirements, but it's pretty easy for a savvy kid to fake their birthdate to gain access."
    },
    {
      "ref": "[D176]",
      "area": "content",
      "claim": "A parent reports that the app contains sexual content and suggestive comments in chat.",
      "stance": "risk",
      "quote": "Avatars can be dressed in underwear or bikinis but don't do anything suggestive or sexual; however, chat feature is rife with flirting and suggestive comments. Also, since users can openly chat with others in the same room, there's an opportunity for users to be virtually approached by strangers and may say suggestive things to them."
    },
    {
      "ref": "[D176]",
      "area": "developer_record",
      "claim": "A parent reports that the developer has had regulatory actions or fines related to data collection.",
      "stance": "neutral",
      "quote": "The privacy policy reiterates that users must be at least 13 and specifies that any personal information shared in the game, including birth date and location, even through chat and private message, can be captured, stored, and used."
    }
  ]
}
